values
('bmlt-labmanagement1-practice-001','BMLT','BMLT NHPC Licensing','mcq','free',1,'{"question":"The primary purpose of internal quality control (IQC) is to:","translation":"","options":["Monitor day-to-day analytical performance","Replace external assessment","Issue patient reports faster","Select blood donors"],"correctIndex":0,"explanation":"IQC ले दैनिक test performance र analytical errors निगरानी गर्छ।","explanationNe":"IQC ले दैनिक test performance र analytical errors निगरानी गर्छ।","topic":"Laboratory Management, Quality Assurance & Safety"}'::jsonb,true),
('bmlt-labmanagement1-practice-002','BMLT','BMLT NHPC Licensing','mcq','free',2,'{"question":"External quality assessment (EQA) mainly evaluates:","translation":"","options":["Laboratory performance compared with other laboratories or reference targets","Staff attendance","Patient waiting time only","Reagent colour"],"correctIndex":0,"explanation":"EQA मा बाह्य रूपमा दिइएको sample जाँचेर अन्य lab वा target value सँग तुलना गरिन्छ।","explanationNe":"EQA मा बाह्य रूपमा दिइएको sample जाँचेर अन्य lab वा target value सँग तुलना गरिन्छ।","topic":"Laboratory Management, Quality Assurance & Safety"}'::jsonb,true),
('bmlt-labmanagement1-practice-003','BMLT','BMLT NHPC Licensing','mcq','free',3,'{"question":"A standard operating procedure (SOP) is:","translation":"","options":["A written step-by-step procedure for a task","A patient diagnosis","A reagent brand name","A laboratory timetable only"],"correctIndex":0,"explanation":"SOP ले कुनै काम कसरी सही र सुरक्षित गर्ने भन्ने लिखित चरणहरू दिन्छ।","explanationNe":"SOP ले कुनै काम कसरी सही र सुरक्षित गर्ने भन्ने लिखित चरणहरू दिन्छ।","topic":"Laboratory Management, Quality Assurance & Safety"}'::jsonb,true),
('bmlt-labmanagement1-practice-004','BMLT','BMLT NHPC Licensing','mcq','free',4,'{"question":"Which document records the temperature of a laboratory refrigerator?","translation":"","options":["Temperature log","Patient consent form","Requisition register","Duty roster"],"correctIndex":0,"explanation":"Refrigerator temperature log मा नियमित तापक्रम रेकर्ड गरिन्छ।","explanationNe":"Refrigerator temperature log मा नियमित तापक्रम रेकर्ड गरिन्छ।","topic":"Laboratory Management, Quality Assurance & Safety"}'::jsonb,true),
('bmlt-labmanagement1-practice-005','BMLT','BMLT NHPC Licensing','mcq','free',5,'{"question":"A laboratory should reject a sample when it is:","translation":"","options":["Unlabelled or incorrectly identified","Collected in a suitable tube","Adequate in quantity","Properly transported"],"correctIndex":0,"explanation":"पहिचान नभएको वा गलत label भएको sample बाट गलत patient result आउन सक्छ, त्यसैले reject गर्नुपर्छ।","explanationNe":"पहिचान नभएको वा गलत label भएको sample बाट गलत patient result आउन सक्छ, त्यसैले reject गर्नुपर्छ।","topic":"Laboratory Management, Quality Assurance & Safety"}'::jsonb,true),
('bmlt-labmanagement1-practice-006','BMLT','BMLT NHPC Licensing','mcq','free',6,'{"question":"The most important first step after a needle-stick injury is to:","translation":"","options":["Wash the area immediately with soap and water","Squeeze aggressively for several minutes","Apply bleach","Ignore it if no blood is visible"],"correctIndex":0,"explanation":"Needle-stick पछि तुरुन्त साबुन र पानीले धुनुहोस् र तुरुन्त exposure reporting/medical assessment गर्नुहोस्।","explanationNe":"Needle-stick पछि तुरुन्त साबुन र पानीले धुनुहोस् र तुरुन्त exposure reporting/medical assessment गर्नुहोस्।","topic":"Laboratory Management, Quality Assurance & Safety"}'::jsonb,true),
('bmlt-labmanagement1-practice-007','BMLT','BMLT NHPC Licensing','mcq','free',7,'{"question":"Used needles should be discarded into:","translation":"","options":["Puncture-resistant sharps container","Open waste basket","Cardboard box","General paper bin"],"correctIndex":0,"explanation":"प्रयोग भएको needle puncture-resistant sharps container मा तुरुन्त फाल्नुपर्छ।","explanationNe":"प्रयोग भएको needle puncture-resistant sharps container मा तुरुन्त फाल्नुपर्छ।","topic":"Laboratory Management, Quality Assurance & Safety"}'::jsonb,true),
('bmlt-labmanagement1-practice-008','BMLT','BMLT NHPC Licensing','mcq','free',8,'{"question":"The biohazard symbol indicates:","translation":"","options":["Potential biological hazard","Flammable liquid only","Radioactive material only","Compressed gas"],"correctIndex":0,"explanation":"Biohazard चिन्हले संक्रमण गराउन सक्ने जैविक जोखिम जनाउँछ।","explanationNe":"Biohazard चिन्हले संक्रमण गराउन सक्ने जैविक जोखिम जनाउँछ।","topic":"Laboratory Management, Quality Assurance & Safety"}'::jsonb,true),
('bmlt-labmanagement1-practice-009','BMLT','BMLT NHPC Licensing','mcq','free',9,'{"question":"Which practice helps prevent specimen mix-up?","translation":"","options":["Use at least two patient identifiers at collection","Label tubes later from memory","Keep all samples in one open tray","Use the same label for multiple patients"],"correctIndex":0,"explanation":"Sample लिँदा patient का कम्तीमा दुई identifiers मिलाएर तुरुन्त label गर्नुपर्छ।","explanationNe":"Sample लिँदा patient का कम्तीमा दुई identifiers मिलाएर तुरुन्त label गर्नुपर्छ।","topic":"Laboratory Management, Quality Assurance & Safety"}'::jsonb,true),
('bmlt-labmanagement1-practice-010','BMLT','BMLT NHPC Licensing','mcq','free',10,'{"question":"A laboratory incident should be:","translation":"","options":["Reported and documented according to policy","Hidden to avoid blame","Discussed only informally","Deleted from records"],"correctIndex":0,"explanation":"Incident report गर्दा कारण पत्ता लगाउन र पुनः घटना रोक्न मद्दत हुन्छ।","explanationNe":"Incident report गर्दा कारण पत्ता लगाउन र पुनः घटना रोक्न मद्दत हुन्छ।","topic":"Laboratory Management, Quality Assurance & Safety"}'::jsonb,true),
('bmlt-labmanagement1-practice-011','BMLT','BMLT NHPC Licensing','mcq','free',11,'{"question":"The main purpose of a laboratory audit is to:","translation":"","options":["Check compliance and identify opportunities for improvement","Punish all staff","Increase test prices","Replace training"],"correctIndex":0,"explanation":"Audit ले प्रक्रियाहरू मापदण्डअनुसार छन् कि छैनन् जाँच्छ र सुधारका क्षेत्र पहिचान गर्छ।","explanationNe":"Audit ले प्रक्रियाहरू मापदण्डअनुसार छन् कि छैनन् जाँच्छ र सुधारका क्षेत्र पहिचान गर्छ।","topic":"Laboratory Management, Quality Assurance & Safety"}'::jsonb,true),
('bmlt-labmanagement1-practice-012','BMLT','BMLT NHPC Licensing','mcq','free',12,'{"question":"Which is an example of a pre-analytical error?","translation":"","options":["Wrong patient identification","Incorrect calibration calculation","Transcription of final report","Wrong reference interval printed"],"correctIndex":0,"explanation":"Patient identification, collection र transport pre-analytical चरणका भाग हुन्।","explanationNe":"Patient identification, collection र transport pre-analytical चरणका भाग हुन्।","topic":"Laboratory Management, Quality Assurance & Safety"}'::jsonb,true),
('bmlt-labmanagement1-practice-013','BMLT','BMLT NHPC Licensing','mcq','free',13,'{"question":"Which is an analytical-phase error?","translation":"","options":["Incorrect pipetting during assay","Wrong patient name at collection","Delayed sample transport","Missing request form"],"correctIndex":0,"explanation":"Assay चलाउँदा गलत pipetting हुनु analytical error हो।","explanationNe":"Assay चलाउँदा गलत pipetting हुनु analytical error हो।","topic":"Laboratory Management, Quality Assurance & Safety"}'::jsonb,true),
