('bmlt-labmanagement1-practice-021','BMLT','BMLT NHPC Licensing','mcq','free',21,'{"question":"A reagent beyond its expiry date should generally be:","translation":"","options":["Not used for patient testing","Used if the colour looks normal","Mixed with fresh reagent","Relabelled with a new date"],"correctIndex":0,"explanation":"Expiry सकिएको reagent प्रयोग गर्नु हुँदैन; manufacturer र lab policy पालना गर्नुपर्छ।","explanationNe":"Expiry सकिएको reagent प्रयोग गर्नु हुँदैन; manufacturer र lab policy पालना गर्नुपर्छ।","topic":"Laboratory Management, Quality Assurance & Safety"}'::jsonb,true),
