('bmlt-labmanagement1-practice-024','BMLT','BMLT NHPC Licensing','mcq','free',24,'{"question":"Confidential patient information should be shared with:","translation":"","options":["Authorized personnel involved in care","Anyone asking at reception","Other patients","Public social media"],"correctIndex":0,"explanation":"Patient data गोप्य राखी authorized व्यक्तिसँग मात्र आवश्यकताअनुसार साझा गर्नुपर्छ।","explanationNe":"Patient data गोप्य राखी authorized व्यक्तिसँग मात्र आवश्यकताअनुसार साझा गर्नुपर्छ।","topic":"Laboratory Management, Quality Assurance & Safety"}'::jsonb,true),
