('bmlt-labmanagement1-mock-003','BMLT','BMLT NHPC Licensing','mock','free',3,'{"question":"A Westgard 1-2s rule is generally considered a:","translation":"","options":["Warning rule","Automatic rejection rule in every situation","Calibration method","Specimen rejection code"],"correctIndex":0,"explanation":"1-2s rule सामान्यतया warning rule हो; थप नियम र context हेरेर निर्णय गरिन्छ।","explanationNe":"1-2s rule सामान्यतया warning rule हो; थप नियम र context हेरेर निर्णय गरिन्छ।","topic":"Laboratory Management, Quality Assurance & Safety"}'::jsonb,true),
('bmlt-labmanagement1-mock-004','BMLT','BMLT NHPC Licensing','mock','free',4,'{"question":"A sudden shift in QC results may indicate:","translation":"","options":["A systematic error","Only random patient variation","Correct patient identification","A normal reference interval"],"correctIndex":0,"explanation":"QC मा अचानक shift देखिनु systematic error वा method/reagent परिवर्तनको संकेत हुन सक्छ।","explanationNe":"QC मा अचानक shift देखिनु systematic error वा method/reagent परिवर्तनको संकेत हुन सक्छ।","topic":"Laboratory Management, Quality Assurance & Safety"}'::jsonb,true),
('bmlt-labmanagement1-mock-005','BMLT','BMLT NHPC Licensing','mock','free',5,'{"question":"A gradual trend in QC results may suggest:","translation":"","options":["Progressive analytical change","Perfect stability","Patient misidentification only","No need for investigation"],"correctIndex":0,"explanation":"QC trend ले reagent deterioration, instrument drift वा calibration समस्या देखाउन सक्छ।","explanationNe":"QC trend ले reagent deterioration, instrument drift वा calibration समस्या देखाउन सक्छ।","topic":"Laboratory Management, Quality Assurance & Safety"}'::jsonb,true),
